pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;
    function setUp() public { c = new ERCDDAToken(0, "0", "0"); }
    function testFuzz_property(uint256 initialSupply, uint256 burnValue) public {
        initialSupply = bound(initialSupply, 1, type(uint64).max);
        burnValue = bound(burnValue, 1, initialSupply);

        c = new ERCDDAToken(initialSupply, "0", "0");
        address owner = address(this);
        uint256 totalBefore = c.totalSupply();

        vm.prank(owner);
        bool success = c.burn(burnValue);
        require(success, "burn must succeed");

        uint256 totalAfter = c.totalSupply();

        assertEq(totalBefore - totalAfter, burnValue, "totalSupply reduction must equal burned amount");
    }
}
